type mockConstructorTestingTNewMockHolder interface {
	mock.TestingT
	Cleanup(func())
}

// NewMockHolder creates a new instance of MockHolder. It also registers a testing interface on the mock and a cleanup function to assert the mocks expectations.
func NewMockHolder(t mockConstructorTestingTNewMockHolder) *MockHolder {
	mock := &MockHolder{}
	mock.SetMock(&mock.Mock)
	mock.Mock.Test(t)
	t.Cleanup(func() { mock.AssertExpectations(t) })
	return mock
}
